// generated by gemini-3.5-flash-lite for PR #5792 (round 0): flatten_unflatten_roundtrip
// intent: Verify that flattening and then unflattening a complex structured JSON restores the original value identically.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json j = {
            {"foo", {{"bar", "baz"}, {"one", 1}}},
            {"arr", {1, 2, 3, {{"sub", true}}}}
        };
        auto flat = j.flatten();
        auto unflat = flat.unflatten();
        std::cout << (j == unflat) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
